249	        if (owner.isNew()) {
250	            if (owner.getCustomerCode() == null) {
251	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
252	            }
253	            if (owner.getNamesakeCount() == null) {
254	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
