261	    /**
262	     * Count the existing owners (before this create) that share the given first and last name,
263	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
264	     */
265	    private int countNamesakes(String firstName, String lastName) {
266	        if (firstName == null || lastName == null) {
267	            return 0;
268	        }
269	        return (int) ownerRepository.findAll().stream()
270	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
271	                && lastName.equalsIgnoreCase(owner.getLastName()))
272	            .count();
273	    }
