275	    /**
276	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
277	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
278	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
279	     * 4-digit zero-padded sequence equal to one more than the current number of owners
280	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
281	     */
282	    private String generateCustomerCode(String city, String lastName) {
283	        String cityName = city == null ? "" : city;
284	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
285	        String name = lastName == null ? "" : lastName;
286	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
287	        long sequence = countOwnersInCity(cityName) + 1L;
288	        return String.format("%s-%s-%04d", city3, last3, sequence);
289	    }
290	
291	    /**
292	     * Count the existing owners whose city matches the given city, compared case-insensitively,
293	     * used to derive the per-city sequence of the customer code.
294	     */
295	    private long countOwnersInCity(String city) {
296	        if (city == null) {
297	            return 0L;
298	        }
299	        return ownerRepository.findAll().stream()
300	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
301	            .count();
302	    }
