320	    @Override
321	    @Transactional(readOnly = true)
322	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
323	        String normalized = normalizeTelephone(telephone);
324	        if (normalized == null) {
325	            return false;
326	        }
327	        return ownerRepository.findAll().stream()
328	            .map(owner -> normalizeTelephone(owner.getTelephone()))
329	            .anyMatch(normalized::equals);
330	    }
