332	    @Override
333	    @Transactional(readOnly = true)
334	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
335	        String normalizedLastName = normalizeHouseholdValue(lastName);
336	        String normalizedAddress = normalizeHouseholdAddress(address);
337	        if (normalizedLastName.isEmpty() || normalizedAddress.isEmpty()) {
338	            return false;
339	        }
340	        return ownerRepository.findAll().stream()
341	            .anyMatch(owner -> normalizedLastName.equals(normalizeHouseholdValue(owner.getLastName()))
342	                && normalizedAddress.equals(normalizeHouseholdAddress(owner.getAddress())));
343	    }
344	
345	    @Override
346	    @Transactional(readOnly = true)
347	    public String householdIdFor(String lastName, String address) throws DataAccessException {
348	        String key = normalizeHouseholdValue(lastName) + "\u0000" + normalizeHouseholdAddress(address);
349	        try {
350	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
351	            StringBuilder sb = new StringBuilder(32);
352	            for (int i = 0; i < 8; i++) {
353	                sb.append(String.format("%02X", digest[i]));
354	            }
355	            return sb.toString();
356	        } catch (NoSuchAlgorithmException ex) {
357	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
358	        }
359	    }
360	
361	    /**
362	     * Normalizes a household field (last name or address) for duplicate comparison by trimming,
363	     * collapsing runs of whitespace to a single space and lower-casing, so differently cased or
364	     * spaced but equivalent values compare equal.
365	     */
366	    private static String normalizeHouseholdValue(String value) {
367	        if (value == null) {
368	            return "";
369	        }
370	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
371	    }
372	
373	    /**
374	     * Normalizes an address for household comparison by first applying the canonical address
375	     * normalization (trim, collapse whitespace, upper-case and expand common abbreviations) and
376	     * then the shared household-value normalization, so every address comparison uses the same
377	     * normalized form regardless of how the value was originally supplied.
378	     */
379	    private static String normalizeHouseholdAddress(String address) {
380	        return normalizeHouseholdValue(AddressNormalizer.normalize(address));
381	    }
382	
383	    /**
384	     * Reduces a telephone number to its canonical E.164 form so that differently formatted but
385	     * equivalent numbers compare equal. A value already stored that cannot form valid E.164
386	     * (e.g. unusual legacy data) falls back to its digits-only form rather than failing lookup.
387	     */
388	    private static String normalizeTelephone(String telephone) {
389	        if (telephone == null) {
390	            return null;
391	        }
392	        try {
393	            return TelephoneNormalizer.toE164(telephone);
394	        } catch (InvalidTelephoneException ex) {
395	            return telephone.replaceAll("\\D", "");
396	        }
397	    }
